// Read the owner-only comparison generated by verify_selected_catalogue.py.
import assert from 'node:assert/strict';
import {buildSelectedReference,scoreSelected,selectedWork,type SelectedMetadata} from '../../../src/lib/social/taste-selected-rules';
import type {TasteV2Features,TasteV2Medium} from '../../../src/lib/social/taste-v2';

type Row = {id:string;family:string;features:TasteV2Features;facts:SelectedMetadata;credits:SelectedMetadata['credits'];
  voteAverage:number|null;voteCount:number;vector:number[]|null;stars:number;native:number;lower:number;
  exact:Record<string,number>;public:Record<string,number>;expected:{score:number;rule:string}};
async function fullCatalogue() {
  const [source,expected,ids,contents]=await Promise.all([Bun.file(Bun.argv[3]).json(),Bun.file(Bun.argv[4]).json(),
    Bun.file(Bun.argv[5]).json(),Bun.file(Bun.argv[6]).arrayBuffer()]);
  const all=new Float64Array(contents), size=all.length/ids.length;
  assert(Number.isInteger(size));
  const vectors=new Map<string,number[]>((ids as string[]).map((id,i)=>[id,Array.from(all.subarray(i*size,(i+1)*size))]));
  type Fresh=Row&{medium:TasteV2Medium;known:boolean;ratingAt:string|null;donorNative:number|null;publicNative:number|null;
    bothRemovals:number|null;exactDonorNative?:Record<string,number>;publicDonorNative?:Record<string,number>};
  for(const medium of ['movie','show'] as const) {
    const rows=(source.rows as Fresh[]).filter(r=>r.medium===medium);
    const seen=new Set(rows.filter(r=>r.known).map(r=>r.family));
    for(const plot of [true,false]) {
      const works=rows.map(r=>selectedWork(r.id,r.family,medium,r.features,{...r.facts,credits:r.credits,
        audience:r.voteAverage===null ? null : {score:r.voteAverage,votes:r.voteCount},synopsis:plot?vectors.get(r.id):undefined}));
      const ref=buildSelectedReference(rows.flatMap((r,k)=>r.ratingAt?[{...works[k],stars:r.stars,native:r.donorNative,publicNative:r.publicNative}]:[]));
      let exact=0,noSynopsis=0;
      const start=performance.now();
      for(const [i,r] of rows.entries()) {
        if(r.native==null || r.ratingAt) continue;
        const active=seen.has(r.family) || r.known;
        function residuals(points:Record<string,number>|undefined) {return points || active ? new Map(Object.entries(points??{})) : undefined;}
        const actual=scoreSelected(ref,works[i],r.native,()=>r.bothRemovals,{exact:residuals(r.exactDonorNative),public:residuals(r.publicDonorNative)});
        const baseline=expected.rows[r.id];
        if(actual.score===baseline.score && actual.rule===baseline.rule) exact++;
        else {
          assert(!plot && baseline.rule==='story-credit' && actual.score===r.native && actual.rule==='personal',
            JSON.stringify({id:r.id,actual,baseline}));
          noSynopsis++;
        }
      }
      console.log({medium,plot,exact,noSynopsis,elapsedMs:Math.round(performance.now()-start)});
    }
  }
}
if(Bun.argv[2]==='--catalogue') {
  await fullCatalogue();
} else {
const rows=await Bun.file(Bun.argv[2]).json() as Record<TasteV2Medium,Row[]>;
for(const medium of ['movie','show'] as const) {
  for(const plot of [true,false]) {
    const works=rows[medium].map(r=>selectedWork(r.id,r.family,medium,r.features,{...r.facts,credits:r.credits,
      audience:r.voteAverage===null ? null : {score:r.voteAverage,votes:r.voteCount},synopsis:plot ? r.vector??undefined : undefined}));
    const ref=buildSelectedReference(works.map((w,i)=>({...w,stars:rows[medium][i].stars,native:null,publicNative:null})));
    let exact=0,noSynopsis=0;
    rows[medium].forEach((r,i)=>{
      const actual=scoreSelected(ref,works[i],r.native,()=>r.lower,{
        exact:new Map(Object.entries(r.exact)),public:new Map(Object.entries(r.public))});
      if(actual.score===r.expected.score && actual.rule===r.expected.rule) exact++;
      else {
        assert(!plot && r.expected.rule==='story-credit' && actual.score===r.native && actual.rule==='personal',
          JSON.stringify({id:r.id,medium,plot,actual,expected:r.expected}));
        noSynopsis++;
      }
    });
    console.log({medium,plot,exact,noSynopsis});
  }
}
}
